with deduped as (select *, row_number() over (partition by region order by opened_date desc nulls first, id) as latest_rank from stores qualify latest_rank = 1), deduped_stores as (select * from deduped qualify rank() over (partition by city, region order by sqft nulls first) = 1), enriched as (select *, max(sqft) over w_ordered as running_max_sqft, avg(sqft) over w_ordered as running_avg_sqft, sum(sqft) over w_ordered as running_sum_sqft, min(sqft) over w_ordered as running_min_sqft, dense_rank() over (order by sqft nulls last) as sqft_dense_rank from deduped_stores window w_ordered as (partition by region order by latest_rank, id rows between unbounded preceding and current row)), with_windows as (select *, count(running_min_sqft) over (partition by city, region order by sqft_dense_rank, id rows between 3 preceding and current row) as last4_count_running_min_sqft, avg(running_min_sqft) over (partition by city, region order by sqft_dense_rank, id rows between 3 preceding and current row) as last4_avg_running_min_sqft, min(running_min_sqft) over (partition by city, region order by sqft_dense_rank, id rows between 3 preceding and current row) as last4_min_running_min_sqft from enriched where running_avg_sqft <= 6900) select id, store_name, opened_date, sqft, latest_rank, running_avg_sqft, running_min_sqft, last4_count_running_min_sqft, lead(sqft_dense_rank, 1) over (partition by city order by opened_date, id) as next_sqft_dense_rank, last_value(running_max_sqft, true) over (order by running_sum_sqft, id rows between unbounded preceding and current row) as last_known_running_max_sqft from with_windows;
